{
    uint8_t free_cnt = 0;
    for (int i = 0; i < MAX_NUM_CMD_SHORT_BUF; i++) 
    {
        uint32_t pattern = *((uint32_t*)(cif_env.cmd_addr_short[i] - EVENT_HEAD_LEN));

