200	  void *arg;
201	};
202	
203	static volatile bool g_sched_started;
204	static volatile unsigned int g_sched_suspended;
205	static sem_t g_sched_gate = SEM_INITIALIZER(0);
206	
207	/* FreeRTOS priority 0..9 (rtos_pub.c has already applied
208	 * BK_PRIORITY_TO_NATIVE_PRIORITY) spread linearly over NuttX
209	 * SCHED_PRIORITY_MIN..MAX, the projection a7de5d2 validated on the board
210	 * (wifi/bk7258_wifi_osal.c:66-78), here fed the native value directly.
211	 */
212	
213	static int armino_native_priority(UBaseType_t prio)
214	{
215	  const unsigned int top = FREERTOS_MAX_PRIORITIES - 1;
216	
217	  if (prio > top)
218	    {
219	      prio = top;
220	    }
221	
222	  return SCHED_PRIORITY_MIN +
223	         (int)((prio * (SCHED_PRIORITY_MAX - SCHED_PRIORITY_MIN) + top / 2) /
224	               top);
225	}
226	
227	static int armino_task_entry(int argc, char *argv[])
228	{
229	  struct armino_task_s *task;
230	  TaskFunction_t fn;
231	  void *arg;
232	
233	  if (argc < 2)
234	    {
235	      return -EINVAL;
236	    }
237	
238	  task = (struct armino_task_s *)(uintptr_t)strtoul(argv[1], NULL, 16);
239	  fn = task->fn;
240	  arg = task->arg;
241	  kmm_free(task);
242	
243	  /* FreeRTOS runs no task before vTaskStartScheduler(); entry_main()
244	   * creates its main and app threads before it.
245	   */
246	
247	  if (!g_sched_started)
248	    {
249	      nxsem_wait_uninterruptible(&g_sched_gate);
250	      nxsem_post(&g_sched_gate);
251	    }
252	
253	  fn(arg);
254	  return 0;
255	}
256	
257	static BaseType_t armino_task_create(TaskFunction_t fn, const char *name,
258	                                     uint16_t depth, void *arg,
259	                                     UBaseType_t prio, TaskHandle_t *handle)
260	{
261	  struct armino_task_s *task;
262	  char ptr[2 + sizeof(void *) * 2 + 1];
263	  char *argv[2];
264	  int pid;
265	
266	  task = kmm_malloc(sizeof(*task));
267	  if (task == NULL)
268	    {
269	      return pdFAIL;
270	    }
271	
272	  task->fn = fn;
273	  task->arg = arg;
274	  snprintf(ptr, sizeof(ptr), "%lx", (unsigned long)(uintptr_t)task);
275	  argv[0] = ptr;
276	  argv[1] = NULL;
277	
278	  /* depth is in StackType_t words (rtos_pub.c:128 divides bytes by 4).
279	   * ponytail: +1K covers NuttX's TLS and argv copy on top of the Armino
280	   * figure; measure with the stack monitor and trim.
281	   */
282	
283	  pid = kthread_create(name != NULL && name[0] != '\0' ? name : "armino",
284	                       armino_native_priority(prio),
285	                       (int)depth * 4 + 1024, armino_task_entry, argv);
286	  if (pid < 0)
287	    {
288	      syslog(LOG_ERR, "[ARMINO] task %s create failed: %d\n",
289	             name != NULL ? name : "", pid);
290	      kmm_free(task);
291	      return pdFAIL;
292	    }
293	
294	  if (handle != NULL)
295	    {
296	      *handle = (TaskHandle_t)(uintptr_t)pid;
297	    }
298	
299	  return pdPASS;
300	}
