415	/****************************************************************************
416	 * Queues, semaphores, mutexes
417	 ****************************************************************************/
418	
419	struct armino_queue_s
420	{
421	  /* FreeRTOS's Queue_t starts with pcHead, which for a semaphore points at
422	   * the queue itself (queue.c:516). bk_api_ipc.c:868 passes a semaphore
423	   * handle where rtos_get_semaphore() expects its address, and rtos_pub.c
424	   * dereferences it; on FreeRTOS that yields the same handle, so the
425	   * baseline works by accident. Keep the same first word. Board boot
426	   * 2026-10-03 took an unaligned-access fault there (handle read as 0x2,
427	   * the type byte, so the semaphore count landed at 0x6).
428	   *
429	   * Only semaphores set it. A FreeRTOS mutex has pcHead NULL
430	   * (queueQUEUE_IS_MUTEX), which kmm_zalloc() already gives; a data queue
431	   * points it at its storage, so the same slip on a queue fails on the
432	   * baseline too.
433	   */
434	
435	  void *head;
436	  uint8_t type;
437	  union
438	    {
439	      struct file mq;
440	      sem_t sem;
441	      rmutex_t mutex;
442	    } u;
443	  unsigned int id;
444	  UBaseType_t depth;
445	  UBaseType_t item_size;
446	  UBaseType_t max_count;
447	  long hiwater;
448	};
449	
450	typedef struct armino_queue_s *QueueHandle_t;
451	
452	static unsigned int g_queue_id;
453	
454	static long armino_queue_count(QueueHandle_t q);
455	
456	static bool armino_is_semaphore(QueueHandle_t q)
457	{
458	  return q->type == queueQUEUE_TYPE_COUNTING ||
459	         q->type == queueQUEUE_TYPE_BINARY;
460	}
461	
462	static bool armino_is_mutex(QueueHandle_t q)
463	{
464	  return q->type == queueQUEUE_TYPE_MUTEX ||
465	         q->type == queueQUEUE_TYPE_RMUTEX;
466	}
467	
468	static QueueHandle_t armino_sem_create(uint8_t type, UBaseType_t max,
469	                                       UBaseType_t initial)
470	{
471	  QueueHandle_t q = kmm_zalloc(sizeof(*q));
472	
473	  if (q != NULL)
474	    {
475	      q->head = q;
476	      q->type = type;
477	      q->max_count = max;
478	      nxsem_init(&q->u.sem, 0, (int)initial);
479	    }
480	
481	  return q;
482	}
483	
484	QueueHandle_t xQueueGenericCreate(const UBaseType_t len,
485	                                  const UBaseType_t item_size,
486	                                  const uint8_t type)
487	{
488	  struct mq_attr attr;
489	  char name[16];
490	  QueueHandle_t q;
491	  int ret;
492	
493	  /* xSemaphoreCreateBinary() is xQueueGenericCreate(1, 0, BINARY). */
494	
495	  if (type == queueQUEUE_TYPE_BINARY)
496	    {
497	      return armino_sem_create(type, 1, 0);
498	    }
499	
500	  if (item_size > CONFIG_MQ_MAXMSGSIZE || len == 0)
501	    {
502	      syslog(LOG_ERR, "[ARMINO] queue rejected: item %lu (max %d) depth %lu\n",
503	             (unsigned long)item_size, CONFIG_MQ_MAXMSGSIZE,
504	             (unsigned long)len);
505	      return NULL;
506	    }
507	
508	  q = kmm_zalloc(sizeof(*q));
509	  if (q == NULL)
510	    {
511	      return NULL;
512	    }
513	
514	  q->type = queueQUEUE_TYPE_BASE;
515	  q->id = ++g_queue_id;
516	  q->depth = len;
517	  q->item_size = item_size;
518	
519	  attr.mq_maxmsg = (long)len;
520	  attr.mq_msgsize = (long)item_size;
521	  attr.mq_flags = 0;
522	  snprintf(name, sizeof(name), "/armq%u", q->id);
523	  ret = file_mq_open(&q->u.mq, name, O_RDWR | O_CREAT | O_EXCL, 0666, &attr);
524	  if (ret < 0)
525	    {
526	      syslog(LOG_ERR, "[ARMINO] queue %u open failed: %d\n", q->id, ret);
527	      kmm_free(q);
528	      return NULL;
529	    }
530	
531	  /* The open descriptor keeps it alive; the name is not needed. */
532	
533	  file_mq_unlink(name);
534	  syslog(LOG_INFO, "[ARMINO] queue %u: item %lu depth %lu\n", q->id,
535	         (unsigned long)item_size, (unsigned long)len);
536	  return q;
537	}
