707	BaseType_t xQueueReceive(QueueHandle_t q, void *const buf, TickType_t ticks)
708	{
709	  ssize_t ret;
710	
711	  /* Zero timeout: same reasoning as in armino_queue_send(). */
712	
713	  if (ticks == 0 && armino_queue_count(q) == 0)
714	    {
715	      return pdFAIL;
716	    }
717	
718	  if (ticks == portMAX_DELAY)
719	    {
720	      ret = file_mq_receive(&q->u.mq, buf, q->item_size, NULL);
721	    }
722	  else
723	    {
724	      ret = file_mq_tickreceive(&q->u.mq, buf, q->item_size, NULL,
725	                                (sclock_t)ticks);
726	    }
727	
728	  return ret >= 0 ? pdPASS : pdFAIL;
729	}
730	
731	BaseType_t xQueueSemaphoreTake(QueueHandle_t q, TickType_t ticks)
732	{
733	  int ret;
734	
735	  if (armino_is_mutex(q))
736	    {
737	      if (ticks == portMAX_DELAY)
738	        {
739	          ret = nxrmutex_lock(&q->u.mutex);
740	        }
741	      else if (ticks == 0)
742	        {
743	          ret = nxrmutex_trylock(&q->u.mutex);
744	        }
745	      else
746	        {
747	          ret = nxrmutex_ticklock(&q->u.mutex, ticks);
748	        }
749	    }
750	  else if (ticks == portMAX_DELAY)
751	    {
752	      ret = nxsem_wait_uninterruptible(&q->u.sem);
753	    }
754	  else if (ticks == 0)
755	    {
756	      ret = nxsem_trywait(&q->u.sem);
757	    }
758	  else
759	    {
760	      ret = nxsem_tickwait_uninterruptible(&q->u.sem, ticks);
761	    }
762	
763	  return ret == OK ? pdPASS : pdFAIL;
764	}
765	
766	static long armino_queue_count(QueueHandle_t q)
767	{
768	  struct mq_attr attr;
769	  int value = 0;
770	
771	  if (armino_is_semaphore(q))
772	    {
773	      nxsem_get_value(&q->u.sem, &value);
774	      return value;
775	    }
776	
777	  if (armino_is_mutex(q))
778	    {
779	      return 0;
780	    }
781	
782	  return file_mq_getattr(&q->u.mq, &attr) == OK ? attr.mq_curmsgs : 0;
783	}
784	
785	BaseType_t xQueueIsQueueEmptyFromISR(const QueueHandle_t q)
786	{
787	  return armino_queue_count(q) == 0 ? pdTRUE : pdFALSE;
788	}
789	
790	BaseType_t xQueueIsQueueFullFromISR(const QueueHandle_t q)
791	{
792	  long limit = armino_is_semaphore(q) ? (long)q->max_count : (long)q->depth;
793	
794	  return armino_queue_count(q) >= limit ? pdTRUE : pdFALSE;
795	}
