    if (err == 0 && acc_len > 0) {
        while (acc_len > 0
               && (acc[acc_len - 1] == '\n' || acc[acc_len - 1] == '\r')) {
            acc_len--;
        }
        acc[acc_len] = '\0';
        if (cb(acc, acc_len, user) != 0) {
            err = VELA_TLS_ERR_READ;
        }
    }

