759	void bk7258_dac_deinit(void)
760	{
761	  uint32_t v;
762	
763	  bk7258_dac_stop();
764	  (void)bk7258_dac_mute(true);
765	
766	  /* Reverse the analog power-up sequence.  Keep the ana_reg defaults in
767	   * place so a future bk7258_dac_configure() does not have to re-run the
768	   * whole subsystem init.
769	   */
770	
771	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACLEN_BIT, 0x1u, 0);
772	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG21, ANA_REG21_ENIDACL_BIT, 0x1u, 0);
773	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_LENDCOC_BIT, 0x1u, 0);
774	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACDRVEN_BIT, 0x1u, 0);
775	
776	  /* Restore the vendor deinit clock baseline: select XTAL in both the SYS
777	   * mux and AUD block, clear the APLL-only DMIC divider, then power APLL
778	   * down.  This makes the next configure independent of the previous one.
779	   */
780	
781	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
782	  v &= ~AUD_AUDIO_CFG_APLL_SEL;
783	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
784	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
785	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
786	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
787	                      0u);
788	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
789	                      UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
790	                      0u);
791	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
792	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 1u);
793	
794	  g_bk7258_dac_use_apll  = false;
795	  g_bk7258_dac_configured = false;
796	}
