214	/* Queue LPWORK while holding priv->lock.  Pairing the closing check and
215	 * work_queue() under the same lock ensures shutdown either prevents a new
216	 * queue operation or observes an already queued item that cancel_sync can
217	 * cover.  work_queue() is IRQ-safe and does not sleep.
218	 */
219	
220	static void bk7258_schedule_worker_locked(FAR struct bk7258_audio_s *priv)
221	{
222	  if (!priv->closing)
223	    {
224	      (void)work_queue(LPWORK, &priv->work, bk7258_worker, priv, 0);
225	    }
226	}
