228	/* Close the run gate and detach every buffer affected by an asynchronous
229	 * failure.  recover_after_fault distinguishes a synchronous initial-start
230	 * failure from a runtime fault that requires stop plus OUTPUT configure.
231	 * Must be called with priv->lock held.
232	 */
233	
234	static void bk7258_fault_locked(FAR struct bk7258_audio_s *priv, int error,
235	                                bool recover_after_fault)
236	{
237	  FAR struct ap_buffer_s *apb;
238	
239	  priv->dac_running = false;
240	  priv->dma_active = false;
241	  priv->faulted = true;
242	  priv->fault_pending = true;
243	  priv->recover_after_fault = recover_after_fault;
244	  priv->complete_pending = false;
245	  priv->underrun_pending = true;
246	  priv->final_seen = false;
247	
248	  priv->dma_error = error;
249	
250	  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
251	    {
252	      dq_addlast(&apb->dq_entry, &priv->failq);
253	    }
254	}
255	
256	/* Kick off a DMA transfer for the buffer at the head of pendq.  Must be
257	 * called with priv->lock held.  dma_active prevents the same head from being
258	 * programmed twice.  Returns zero if no buffer is queued/already active or
259	 * the transfer starts successfully; otherwise returns a negated errno.
260	 */
261	
262	static int bk7258_start_next_locked(FAR struct bk7258_audio_s *priv)
263	{
264	  FAR struct ap_buffer_s *apb;
265	  struct bk7258_dma_m2p_cfg_s cfg;
266	  int ret;
267	
268	  if (priv->closing || priv->stopping || priv->faulted ||
269	      priv->fault_pending || !priv->dac_running || priv->dma_active)
270	    {
271	      return OK;
272	    }
273	
274	  apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
275	  if (apb == NULL)
276	    {
277	      return OK;
278	    }
279	
280	  cfg.buf          = (uintptr_t)apb->samp;
281	  cfg.buf_len      = apb->nbytes;
282	  cfg.dest         = bk7258_dac_fifo_addr();
283	  cfg.dest_req_mux = BK7258_DMA_REQ_AUDIO_DAC;
284	  /* The DAC FIFO port is a single 32-bit register (AUD_DAC_FPORT).  Each
285	   * word is one stereo frame {R:16, L:16} or two mono samples.  Both
286	   * source and destination widths must be 32-bit so the DMA engine drops
287	   * exactly one word into the FIFO per transfer beat.  Using 16-bit width
288	   * would leave the FIFO half-loaded and the "finish" interrupt would
289	   * never fire.
290	   */
291	
292	  cfg.src_width    = BK7258_DMA_WIDTH_32;
293	  cfg.dst_width    = BK7258_DMA_WIDTH_32;
294	  /* AVDK's reference audio path uses REPEAT + src loop instead of a
295	   * one-shot transfer.  Empirical trace with one_shot=true showed the DMA
296	   * moves only 3 words then stalls (remain_len frozen).  In REPEAT mode
297	   * the engine keeps consuming DREQ pulses from the DAC FIFO until
298	   * transfer_len is reached, which matches the peripheral request timing
299	   * BK7258's audio block appears to expect.
300	   */
301	
302	  cfg.one_shot     = false;
303	  cfg.callback     = bk7258_audio_dma_cb;
304	  cfg.arg          = priv;
305	
306	  /* Clean the source buffer out of D-cache; GDMA reads from RAM. */
307	
308	  up_clean_dcache((uintptr_t)apb->samp,
309	                  (uintptr_t)apb->samp + apb->nbytes);
310	
311	  ret = bk7258_gdma_start_m2p(priv->dma_ch, &cfg);
312	  if (ret < 0)
313	    {
314	      AUD_ERR("gdma_start_m2p failed: %d", ret);
315	      return ret;
316	    }
317	
318	  priv->dma_active = true;
319	  return OK;
320	}
321	
322	/* LPWORK is deliberately not a queue advancer.  It only makes an
323	 * asynchronous fault safe, returns completed/failed buffers, and emits
324	 * deferred upper-half notifications.
325	 */
326	
327	static void bk7258_worker(FAR void *arg)
328	{
329	  FAR struct bk7258_audio_s *priv = arg;
330	  FAR struct ap_buffer_s *apb;
331	  irqstate_t flags;
332	  bool complete;
333	  bool fault_underrun;
334	  bool fault_work;
335	  bool underrun;
336	  int error;
337	  int pa_ret;
338	
339	  flags = spin_lock_irqsave(&priv->lock);
340	  if (priv->closing)
341	    {
342	      spin_unlock_irqrestore(&priv->lock, flags);
343	      return;
344	    }
345	
346	  error = priv->dma_error < 0 ? priv->dma_error : -EIO;
347	  fault_work = priv->fault_pending;
348	  spin_unlock_irqrestore(&priv->lock, flags);
349	
350	  if (fault_work)
351	    {
352	      if (priv->configured)
353	        {
354	          (void)bk7258_dac_mute(true);
355	        }
356	
357	      if (priv->dma_ch >= 0)
358	        {
359	          bk7258_gdma_stop(priv->dma_ch);
360	        }
361	
362	      bk7258_dac_stop();
363	      pa_ret = bk7258_pa_disable();
364	      if (pa_ret < 0)
365	        {
366	          AUD_ERR("PA disable after DMA fault failed: %d", pa_ret);
367	        }
368	
369	      flags = spin_lock_irqsave(&priv->lock);
370	      priv->fault_pending = false;
371	      spin_unlock_irqrestore(&priv->lock, flags);
372	    }
373	
374	  for (; ; )
375	    {
376	      flags = spin_lock_irqsave(&priv->lock);
377	      if (priv->closing)
378	        {
379	          spin_unlock_irqrestore(&priv->lock, flags);
380	          return;
381	        }
382	
383	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->doneq);
384	      spin_unlock_irqrestore(&priv->lock, flags);
385	
386	      if (apb == NULL)
387	        {
388	          break;
389	        }
390	
391	      bk7258_notify_dequeue(priv, apb, OK);
392	    }
393	
394	  for (; ; )
395	    {
396	      flags = spin_lock_irqsave(&priv->lock);
397	      if (priv->closing)
398	        {
399	          spin_unlock_irqrestore(&priv->lock, flags);
400	          return;
401	        }
402	
403	      /* A fault raised after this worker started must be made hardware-safe
404	       * by the requeued invocation before any error DEQUEUE is emitted.
405	       */
406	
407	      if (priv->fault_pending)
408	        {
409	          spin_unlock_irqrestore(&priv->lock, flags);
410	          return;
411	        }
412	
413	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->failq);
414	      spin_unlock_irqrestore(&priv->lock, flags);
415	
416	      if (apb == NULL)
417	        {
418	          break;
419	        }
420	
421	      bk7258_notify_dequeue(priv, apb, error);
422	    }
423	
424	  flags = spin_lock_irqsave(&priv->lock);
425	  if (priv->closing)
426	    {
427	      spin_unlock_irqrestore(&priv->lock, flags);
428	      return;
429	    }
430	
431	  fault_underrun = priv->faulted || fault_work;
432	  underrun = priv->underrun_pending;
433	  priv->underrun_pending = false;
434	
435	  /* A synchronous initial-start failure is recoverable once hardware is
436	   * safe and every accepted buffer has completed its error callback.  Keep
437	   * faulted asserted during those callbacks so upper-half refill attempts
438	   * are rejected.  Runtime faults never set recover_after_fault.
439	   */
440	
441	  if (priv->recover_after_fault && !priv->fault_pending &&
442	      dq_peek(&priv->failq) == NULL)
443	    {
444	      priv->recover_after_fault = false;
445	      priv->faulted = false;
446	      priv->dma_error = OK;
447	    }
448	
449	  if (priv->final_seen && !priv->faulted && !priv->dma_active &&
450	      dq_peek(&priv->pendq) == NULL)
451	    {
452	      priv->final_seen = false;
453	      priv->complete_pending = true;
454	    }
455	
456	  complete = priv->complete_pending && !priv->dma_active &&
457	             dq_peek(&priv->pendq) == NULL &&
458	             dq_peek(&priv->doneq) == NULL &&
459	             dq_peek(&priv->failq) == NULL;
460	  if (complete)
461	    {
462	      priv->complete_pending = false;
463	    }
464	
465	  spin_unlock_irqrestore(&priv->lock, flags);
466	
467	  if (underrun)
468	    {
469	      bk7258_notify_underrun(priv, fault_underrun ? error : -EPIPE);
470	    }
471	
472	  if (complete)
473	    {
474	      bk7258_notify_complete(priv);
475	    }
476	}
477	
478	/* DMA IRQ callback.  IRQ completion and enqueue are the only queue
479	 * advancers.  Faults only close the run gate and defer all sleeping, PA,
480	 * hardware-stop and upper-half work to LPWORK.
481	 */
482	
483	void bk7258_audio_dma_cb(int ch, uint32_t event, FAR void *arg)
484	{
485	  FAR struct bk7258_audio_s *priv = arg;
486	  FAR struct ap_buffer_s *apb;
487	  irqstate_t flags;
488	  bool need_worker = false;
489	  int ret;
490	
491	  (void)ch;
492	
493	  flags = spin_lock_irqsave(&priv->lock);
494	
495	  if ((event & BK7258_DMA_EVENT_BUS_ERROR) != 0u)
496	    {
497	      if (priv->dac_running || priv->dma_active)
498	        {
499	          AUD_ERR("DMA bus error");
500	          bk7258_fault_locked(priv, -EIO, false);
501	          need_worker = true;
502	        }
503	    }
504	  else if ((event & BK7258_DMA_EVENT_FULL) != 0u && priv->dma_active)
505	    {
506	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
507	      priv->dma_active = false;
508	      if (apb != NULL)
509	        {
510	          dq_addlast(&apb->dq_entry, &priv->doneq);
511	          need_worker = true;
512	        }
513	
514	      if (priv->dac_running && !priv->closing && !priv->stopping &&
515	          !priv->faulted)
516	        {
517	          ret = bk7258_start_next_locked(priv);
518	          if (ret < 0)
519	            {
520	              bk7258_fault_locked(priv, ret, false);
521	              need_worker = true;
522	            }
523	          else if (!priv->dma_active)
524	            {
525	              if (priv->final_seen)
526	                {
527	                  priv->complete_pending = true;
528	                }
529	              else
530	                {
531	                  priv->underrun_pending = true;
532	                }
533	
534	              need_worker = true;
535	            }
536	        }
537	    }
538	
539	  if (need_worker)
540	    {
541	      bk7258_schedule_worker_locked(priv);
542	    }
543	
544	  spin_unlock_irqrestore(&priv->lock, flags);
545	}
