610	#ifdef CONFIG_AUDIO_MULTI_SESSION
611	static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
612	                            FAR void *session,
613	                            FAR const struct audio_caps_s *caps)
614	#else
615	static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
616	                            FAR const struct audio_caps_s *caps)
617	#endif
618	{
619	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
620	
621	#ifdef CONFIG_AUDIO_MULTI_SESSION
622	  (void)session;
623	#endif
624	
625	  switch (caps->ac_type)
626	    {
627	      case AUDIO_TYPE_OUTPUT:
628	        {
629	          irqstate_t flags;
630	          uint32_t sample_rate;
631	          uint8_t bpsamp;
632	          uint8_t channels;
633	
634	          sample_rate = caps->ac_controls.hw[0]
635	                      | ((uint32_t)caps->ac_controls.b[3] << 16);
636	          channels = caps->ac_channels;
637	          bpsamp = caps->ac_controls.b[2];
638	
639	          if (bpsamp == 0)
640	            {
641	              bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
642	            }
643	
644	          if (sample_rate == 0)
645	            {
646	              sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
647	            }
648	
649	          if (channels == 0)
650	            {
651	              channels = BK7258_AUDIO_DEFAULT_CHANNELS;
652	            }
653	
654	          if (bpsamp != 16)
655	            {
656	              AUD_ERR("only S16_LE supported (asked for %u)", bpsamp);
657	              return -EINVAL;
658	            }
659	
660	          flags = spin_lock_irqsave(&priv->lock);
661	          if (priv->closing)
662	            {
663	              spin_unlock_irqrestore(&priv->lock, flags);
664	              return -ESHUTDOWN;
665	            }
666	
667	          /* Keep a fault latched through hardware teardown and every error
668	           * DEQUEUE.  A persistent runtime fault additionally requires stop
669	           * to have closed the refill gate before OUTPUT configure recovers
670	           * it.
671	           */
672	
673	          if (priv->faulted &&
674	              (priv->fault_pending || dq_peek(&priv->failq) != NULL))
675	            {
676	              spin_unlock_irqrestore(&priv->lock, flags);
677	              return -EBUSY;
678	            }
679	
680	          if (priv->faulted && !priv->recover_after_fault &&
681	              !priv->stopping)
682	            {
683	              int error = priv->dma_error < 0 ? priv->dma_error : -EIO;
684	              spin_unlock_irqrestore(&priv->lock, flags);
685	              return error;
686	            }
687	
688	          priv->sample_rate = sample_rate;
689	          priv->channels = channels;
690	          priv->bpsamp = bpsamp;
691	
692	          /* Successful OUTPUT configure reopens a normal stop/shutdown or a
693	           * fully drained persistent-fault teardown.
694	           */
695	
696	          priv->stopping = false;
697	          priv->faulted = false;
698	          priv->recover_after_fault = false;
699	          priv->complete_pending = false;
700	          priv->final_seen = false;
701	          priv->underrun_pending = false;
702	          priv->dma_error = OK;
703	
704	          spin_unlock_irqrestore(&priv->lock, flags);
705	
706	          AUD_INFO("configure OUTPUT rate=%lu ch=%u bps=%u",
707	                   (unsigned long)sample_rate, channels, bpsamp);
708	        }
709	        break;
710	
711	      case AUDIO_TYPE_FEATURE:
712	        {
713	          irqstate_t flags;
714	          int ret = OK;
715	
716	          flags = spin_lock_irqsave(&priv->lock);
717	          switch (caps->ac_format.hw)
718	            {
719	              case AUDIO_FU_VOLUME:
720	                {
721	                  uint16_t v = caps->ac_controls.hw[0];
722	                  if (v > 100)
723	                    {
724	                      v = 100;
725	                    }
726	
727	                  priv->volume = (uint8_t)v;
728	                }
729	                break;
730	
731	              case AUDIO_FU_MUTE:
732	                priv->mute = caps->ac_controls.b[0] != 0;
733	                break;
734	
735	              default:
736	                spin_unlock_irqrestore(&priv->lock, flags);
737	                return -EINVAL;
738	            }
739	
740	          /* Always cache feature settings, but touch hardware only for a
741	           * healthy running stream.  The check and bounded register update
742	           * share the fault-state lock so a worker mute cannot be undone by
743	           * a concurrent feature configure.
744	           */
745	
746	          if (priv->configured && priv->dac_running && !priv->closing &&
747	              !priv->stopping && !priv->faulted && !priv->fault_pending)
748	            {
749	              ret = bk7258_apply_volume(priv);
750	              if (ret < 0)
751	                {
752	                  /* An analog SPI failure leaves the DAC mute state
753	                   * unknown.  Fail closed: stop accepting/advancing buffers
754	                   * immediately and let LPWORK turn off DMA, DAC and PA.
755	                   * Keep the original register error visible to the ioctl.
756	                   */
757	
758	                  bk7258_fault_locked(priv, ret, false);
759	                  bk7258_schedule_worker_locked(priv);
760	                }
761	            }
762	
763	          spin_unlock_irqrestore(&priv->lock, flags);
764	          return ret;
765	        }
766	
767	      default:
768	        return -ENOSYS;
769	    }
770	
771	  return OK;
772	}
773	
774	static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev)
775	{
776	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
777	  FAR struct ap_buffer_s *apb;
778	  irqstate_t flags;
779	  int error;
780	  int pa_ret;
781	
782	  /* Temporarily close every producer/run gate before touching hardware.
783	   * Queueing LPWORK is serialized by this same lock.  The barrier is lifted
784	   * only after IRQ/worker teardown and all owned buffers are returned.
785	   */
786	
787	  flags = spin_lock_irqsave(&priv->lock);
788	  priv->closing = true;
789	  priv->dac_running = false;
790	  priv->dma_active = false;
791	  priv->complete_pending = false;
792	  priv->underrun_pending = false;
793	  priv->final_seen = false;
794	  error = priv->dma_error < 0 ? priv->dma_error : -ESHUTDOWN;
795	  spin_unlock_irqrestore(&priv->lock, flags);
796	
797	  /* Stop the IRQ producer first, then synchronously cover any worker queued
798	   * before closing became visible.  Neither operation runs under a spinlock.
799	   */
800	
801	  if (priv->dma_ch >= 0)
802	    {
803	      bk7258_gdma_stop(priv->dma_ch);
804	    }
805	
806	  (void)work_cancel_sync(LPWORK, &priv->work);
807	
808	  if (priv->configured)
809	    {
810	      (void)bk7258_dac_mute(true);
811	    }
812	
813	  bk7258_dac_stop();
814	  pa_ret = bk7258_pa_disable();
815	  if (pa_ret < 0)
816	    {
817	      AUD_ERR("PA disable during shutdown failed: %d", pa_ret);
818	    }
819	
820	  if (priv->dma_ch >= 0)
821	    {
822	      bk7258_gdma_free(priv->dma_ch);
823	      priv->dma_ch = -1;
824	    }
825	
826	  if (priv->configured)
827	    {
828	      bk7258_dac_deinit();
829	    }
830	
831	  /* audio_close keeps upper->status alive until shutdown returns.  Return
832	   * all lower-owned buffers synchronously; callback refill attempts observe
833	   * closing and are rejected without transferring ownership back to us.
834	   */
835	
836	  for (; ; )
837	    {
838	      flags = spin_lock_irqsave(&priv->lock);
839	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->doneq);
840	      spin_unlock_irqrestore(&priv->lock, flags);
841	      if (apb == NULL)
842	        {
843	          break;
844	        }
845	
846	      bk7258_notify_dequeue(priv, apb, OK);
847	    }
848	
849	  for (; ; )
850	    {
851	      flags = spin_lock_irqsave(&priv->lock);
852	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
853	      spin_unlock_irqrestore(&priv->lock, flags);
854	      if (apb == NULL)
855	        {
856	          break;
857	        }
858	
859	      bk7258_notify_dequeue(priv, apb, -ESHUTDOWN);
860	    }
861	
862	  for (; ; )
863	    {
864	      flags = spin_lock_irqsave(&priv->lock);
865	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->failq);
866	      spin_unlock_irqrestore(&priv->lock, flags);
867	      if (apb == NULL)
868	        {
869	          break;
870	        }
871	
872	      bk7258_notify_dequeue(priv, apb, error);
873	    }
874	
875	  /* GDMA is stopped/freed and work_cancel_sync has covered every queued
876	   * worker, so no IRQ or worker can observe the fault reset below.  Keep the
877	   * normal stop gate closed until the next successful OUTPUT configure, but
878	   * make the registered lower half reusable by a future open.
879	   */
880	
881	  flags = spin_lock_irqsave(&priv->lock);
882	  priv->configured = false;
883	  priv->closing = false;
884	  priv->stopping = true;
885	  priv->faulted = false;
886	  priv->fault_pending = false;
887	  priv->recover_after_fault = false;
888	  priv->complete_pending = false;
889	  priv->underrun_pending = false;
890	  priv->final_seen = false;
891	  priv->dma_error = OK;
892	  spin_unlock_irqrestore(&priv->lock, flags);
893	
894	  return OK;
895	}
