1453	static void capture_notify_dequeue(FAR struct bk7258_capture_s *priv,
1454	                                   FAR struct ap_buffer_s *apb, int result)
1455	{
1456	#ifdef CONFIG_AUDIO_MULTI_SESSION
1457	  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, result, NULL);
1458	#else
1459	  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, result);
1460	#endif
1461	}
1462	
1463	/* Same shape as the playback half's bk7258_volume_to_gain(): the upper
1464	 * half speaks 0..100 and the hardware wants the 6-bit ADC gain 0..0x3F.
1465	 * Volume 72 rounds to 45 = 0x2d, Armino's DEFAULT_AUD_ADC_CONFIG().adc_gain.
1466	 */
1467	
1468	#define BK7258_ADC_VOLUME_DEFAULT  72u
1469	#define BK7258_ADC_GAIN_MAX        0x3Fu
1470	
1471	static uint8_t capture_volume_to_gain(uint8_t volume)
1472	{
1473	  return (uint8_t)(((uint32_t)volume * BK7258_ADC_GAIN_MAX) / 100u);
1474	}
