1485	static void capture_start_dma(FAR struct bk7258_capture_s *priv)
1486	{
1487	  FAR struct ap_buffer_s *apb;
1488	  struct bk7258_dma_p2m_cfg_s cfg;
1489	  int ret;
1490	
1491	  /* Buffers queued before AUDIOIOC_START wait here; capture_start() kicks
1492	   * the DMA once the ADC is running.
1493	   */
1494	
1495	  if (!priv->running || priv->paused || priv->stopping ||
1496	      priv->dma_active || priv->dma_ch < 0)
1497	    {
1498	      return;
1499	    }
1500	
1501	  apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
1502	  if (apb == NULL)
1503	    {
1504	      return;
1505	    }
1506	
1507	  cfg.buf         = (uintptr_t)apb->samp;
1508	  cfg.buf_len     = apb->nmaxbytes;
1509	  cfg.src         = bk7258_adc_fifo_addr();
1510	  cfg.src_req_mux = BK7258_DMA_REQ_AUDIO_ADC;
1511	  /* AUD_ADC_FPORT is a single 32-bit register; one beat is a stereo frame
1512	   * or two mono samples.  Both widths 32-bit, same rule as the playback
1513	   * path documents for AUD_DAC_FPORT.
1514	   */
1515	
1516	  cfg.src_width   = BK7258_DMA_WIDTH_32;
1517	  cfg.dst_width   = BK7258_DMA_WIDTH_32;
1518	  cfg.one_shot    = true;
1519	  cfg.callback    = capture_dma_cb;
1520	  cfg.arg         = priv;
1521	
1522	  ret = bk7258_gdma_start_p2m(priv->dma_ch, &cfg);
1523	  if (ret < 0)
1524	    {
1525	      AUD_ERR("gdma_start_p2m failed: %d", ret);
1526	      return;
1527	    }
1528	
1529	  priv->dma_active = true;
1530	  priv->dma_apb    = apb;
1531	}
1532	
1533	static void capture_compact_mono(FAR struct ap_buffer_s *apb)
1534	{
1535	  FAR int16_t *samples = (FAR int16_t *)apb->samp;
1536	  uint32_t frames = (uint32_t)apb->nmaxbytes / 4u;
1537	  uint32_t i;
1538	
1539	  for (i = 0; i < frames; i++)
1540	    {
1541	      samples[i] = samples[2 * i];
1542	    }
1543	
1544	  apb->nbytes = (uint32_t)apb->nmaxbytes / 2u;
1545	}
1546	
1547	static void capture_dma_cb(int ch, uint32_t event, FAR void *arg)
1548	{
1549	  FAR struct bk7258_capture_s *priv = arg;
1550	  FAR struct ap_buffer_s *apb;
1551	  irqstate_t flags;
1552	
1553	  (void)ch;
1554	
1555	  flags = spin_lock_irqsave(&priv->lock);
1556	  apb = priv->dma_apb;
1557	  priv->dma_apb    = NULL;
1558	  priv->dma_active = false;
1559	
1560	  if (apb != NULL && (event & BK7258_DMA_EVENT_BUS_ERROR) == 0)
1561	    {
1562	#ifdef CONFIG_ARMV8M_DCACHE
1563	      up_invalidate_dcache((uintptr_t)apb->samp,
1564	                           (uintptr_t)apb->samp + apb->nmaxbytes);
1565	#endif
1566	      capture_compact_mono(apb);
1567	#ifdef CONFIG_ARMV8M_DCACHE
1568	      up_clean_dcache((uintptr_t)apb->samp,
1569	                      (uintptr_t)apb->samp + apb->nbytes);
1570	#endif
1571	
1572	      dq_rem(&apb->dq_entry, &priv->pendq);
1573	      if (priv->readmode)
1574	        {
1575	          apb->curbyte = 0;
1576	          dq_addlast(&apb->dq_entry, &priv->doneq);
1577	          spin_unlock_irqrestore(&priv->lock, flags);
1578	          nxsem_post(&priv->readsem);
1579	        }
1580	      else
1581	        {
1582	          spin_unlock_irqrestore(&priv->lock, flags);
1583	          capture_notify_dequeue(priv, apb, OK);
1584	        }
1585	    }
1586	  else
1587	    {
1588	      spin_unlock_irqrestore(&priv->lock, flags);
1589	    }
1590	
1591	  capture_start_dma(priv);
1592	}
