1594	static int capture_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
1595	                           FAR struct audio_caps_s *caps)
1596	{
1597	  (void)dev;
1598	  (void)type;
1599	
1600	  /* nxrecorder picks a device by asking AUDIO_TYPE_QUERY and then testing
1601	   * ac_controls.b[0] & AUDIO_TYPE_INPUT (nxrecorder.c:206).  Answering
1602	   * with ac_type = AUDIO_TYPE_INPUT instead leaves b[0] zero and the
1603	   * search reports "No suitable Audio Device".
1604	   */
1605	
1606	  caps->ac_format.hw   = 0;
1607	  caps->ac_controls.w  = 0;
1608	
1609	  switch (caps->ac_type)
1610	    {
1611	      case AUDIO_TYPE_QUERY:
1612	        caps->ac_channels = 1;
1613	        switch (caps->ac_subtype)
1614	          {
1615	            case AUDIO_TYPE_QUERY:
1616	              caps->ac_controls.b[0] = AUDIO_TYPE_INPUT | AUDIO_TYPE_FEATURE;
1617	              caps->ac_format.hw     = 1 << (AUDIO_FMT_PCM - 1);
1618	              break;
1619	
1620	            case AUDIO_FMT_PCM:
1621	              caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
1622	              break;
1623	
1624	            default:
1625	              caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
1626	              break;
1627	          }
1628	        break;
1629	
1630	      case AUDIO_TYPE_INPUT:
1631	        caps->ac_channels = 1;
1632	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
1633	          {
1634	            caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_8K
1635	                                    | AUDIO_SAMP_RATE_16K
1636	                                    | AUDIO_SAMP_RATE_44K
1637	                                    | AUDIO_SAMP_RATE_48K;
1638	          }
1639	        break;
1640	
1641	      case AUDIO_TYPE_FEATURE:
1642	        /* nxplayer's volume command is an AUDIOIOC_CONFIGURE with
1643	         * ac_type=AUDIO_TYPE_FEATURE and ac_format.hw=AUDIO_FU_VOLUME
1644	         * (nxplayer.c:1316-1322), not a dedicated ioctl.  Advertising the
1645	         * unit here is what makes the setting reach the driver at all.
1646	         */
1647	
1648	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
1649	          {
1650	            caps->ac_controls.hw[0] = AUDIO_FU_VOLUME;
1651	          }
1652	        break;
1653	    }
1654	
1655	  return sizeof(struct audio_caps_s);
1656	}
1657	
1658	static int capture_configure(FAR struct audio_lowerhalf_s *dev,
1659	                             FAR const struct audio_caps_s *caps)
1660	{
1661	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
1662	  struct bk7258_adc_cfg_s cfg;
1663	
1664	  if (caps->ac_type == AUDIO_TYPE_FEATURE)
1665	    {
1666	      if (caps->ac_format.hw != AUDIO_FU_VOLUME)
1667	        {
1668	          return -EINVAL;
1669	        }
1670	
1671	      {
1672	        uint16_t v = caps->ac_controls.hw[0];
1673	        if (v > 100)
1674	          {
1675	            v = 100;
1676	          }
1677	
1678	        priv->volume = (uint8_t)v;
1679	      }
1680	
1681	      return bk7258_adc_set_gain(capture_volume_to_gain(priv->volume));
1682	    }
1683	
1684	  if (caps->ac_type != AUDIO_TYPE_INPUT)
1685	    {
1686	      return -EINVAL;
1687	    }
1688	
1689	  priv->samprate = caps->ac_controls.hw[0]
1690	                 | ((uint32_t)caps->ac_controls.b[3] << 16);
1691	  priv->channels = caps->ac_channels;
1692	  priv->bps = caps->ac_controls.b[2];
1693	
1694	  memset(&cfg, 0, sizeof(cfg));
1695	  cfg.samp_rate = priv->samprate;
1696	  cfg.channel   = BK7258_ADC_CHL_L;
1697	  cfg.gain      = capture_volume_to_gain(priv->volume);
1698	  cfg.samp_edge = false;
1699	  cfg.use_apll  = true;
1700	
1701	  return bk7258_adc_configure(&cfg);
1702	}
