1748	
1749	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1750	static int capture_stop(FAR struct audio_lowerhalf_s *dev)
1751	{
1752	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
1753	  FAR struct ap_buffer_s *apb;
1754	  irqstate_t flags;
1755	
1756	  priv->running  = false;
1757	  priv->stopping = true;
1758	
1759	  if (priv->dma_active)
1760	    {
1761	      bk7258_gdma_stop(priv->dma_ch);
1762	      priv->dma_active = false;
1763	      priv->dma_apb    = NULL;
1764	    }
1765	
1766	  bk7258_adc_stop();
1767	
1768	  /* read() mode: the ring belongs to the driver, so nothing goes back to
1769	   * the upper half.  Drop it and wake a blocked reader, which then sees
1770	   * readmode cleared and returns -EAGAIN.
1771	   */
1772	
1773	  if (priv->readmode)
1774	    {
1775	      flags = spin_lock_irqsave(&priv->lock);
1776	      dq_init(&priv->pendq);
1777	      dq_init(&priv->doneq);
1778	      priv->readmode = false;
1779	      spin_unlock_irqrestore(&priv->lock, flags);
1780	      nxsem_post(&priv->readsem);
1781	    }
1782	
1783	  /* nxrecorder's AUDIO_MSG_STOP handler stops streaming but stays in its
1784	   * loop until AUDIO_MSG_COMPLETE arrives (nxrecorder.c:775).  Returning
1785	   * the parked buffers alone is not enough: without COMPLETE the
1786	   * recordthread never exits and nxrecorder_stop()'s pthread_join blocks
1787	   * forever.  Same contract the playback half honours via
1788	   * bk7258_notify_complete().
1789	   */
1790	
1791	  for (; ; )
1792	    {
1793	      flags = spin_lock_irqsave(&priv->lock);
1794	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
1795	      spin_unlock_irqrestore(&priv->lock, flags);
1796	      if (apb == NULL)
1797	        {
1798	          break;
1799	        }
1800	
1801	      capture_notify_dequeue(priv, apb, -ECANCELED);
1802	    }
1803	
1804	  if (!priv->complete_sent)
1805	    {
1806	      priv->complete_sent = true;
1807	      capture_notify_complete(priv);
1808	    }
1809	
1810	  return OK;
1811	}
1812	#endif
1813	
1814	static int capture_shutdown(FAR struct audio_lowerhalf_s *dev)
1815	{
1816	  return capture_stop(dev);
1817	}
