1840	static int capture_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
1841	                         unsigned long arg)
1842	{
1843	  (void)dev;
1844	
1845	  switch (cmd)
1846	    {
1847	      case AUDIOIOC_GETBUFFERINFO:
1848	        {
1849	          FAR struct ap_buffer_info_s *info =
1850	              (FAR struct ap_buffer_info_s *)arg;
1851	
1852	          info->nbuffers    = BK7258_AUDIO_NUM_BUFFERS;
1853	          info->buffer_size = BK7258_AUDIO_BUFFER_SIZE;
1854	        }
1855	        return OK;
1856	
1857	      default:
1858	        return -ENOTTY;
1859	    }
1860	}
1861	
1862	/* Allocate the read() ring once and keep it: 3 x 4 KB, reused by every
1863	 * session.  The lines are invalidated up front so a dirty line left by the
1864	 * heap's previous owner cannot be evicted over DMA data.
1865	 */
1866	
1867	static int capture_read_alloc(FAR struct bk7258_capture_s *priv)
1868	{
1869	  int i;
1870	
1871	  for (i = 0; i < CAPTURE_READ_NBUF; i++)
1872	    {
1873	      FAR struct ap_buffer_s *apb = &priv->rdbuf[i];
1874	
1875	      if (apb->samp != NULL)
1876	        {
1877	          continue;
1878	        }
1879	
1880	      apb->samp = kmm_memalign(32, BK7258_AUDIO_BUFFER_SIZE);
1881	      if (apb->samp == NULL)
1882	        {
1883	          return -ENOMEM;
1884	        }
1885	
1886	      apb->nmaxbytes = BK7258_AUDIO_BUFFER_SIZE;
1887	      up_invalidate_dcache((uintptr_t)apb->samp,
1888	                           (uintptr_t)apb->samp + apb->nmaxbytes);
1889	    }
1890	
1891	  return OK;
1892	}
1893	
1894	/* Blocks for at most CAPTURE_READ_TIMEOUT_MS.  Returns -EAGAIN on timeout
1895	 * or once stop() has ended the session, never 0: ai_agent's recording loop
1896	 * treats 0 as end of stream and -EAGAIN as "retry".
1897	 */
1898	
1899	static int capture_read(FAR struct audio_lowerhalf_s *dev,
1900	                        FAR char *buffer, size_t buflen)
1901	{
1902	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
1903	  FAR struct ap_buffer_s *apb;
1904	  irqstate_t flags;
1905	  bool requeue = false;
1906	  bool readmode;
1907	  size_t n;
1908	  int ret;
1909	  int i;
1910	
1911	  flags = spin_lock_irqsave(&priv->lock);
1912	  readmode = priv->readmode;
1913	  if (!readmode && !dq_empty(&priv->pendq))
1914	    {
1915	      /* nxrecorder-style buffers are queued: the session is taken. */
1916	
1917	      spin_unlock_irqrestore(&priv->lock, flags);
1918	      return -EBUSY;
1919	    }
1920	
1921	  spin_unlock_irqrestore(&priv->lock, flags);
1922	
1923	  if (!readmode)
1924	    {
1925	      ret = capture_read_alloc(priv);
1926	      if (ret < 0)
1927	        {
1928	          return ret;
1929	        }
1930	
1931	      /* Posts the last session left unconsumed must not carry over. */
1932	
1933	      nxsem_reset(&priv->readsem, 0);
1934	
1935	      flags = spin_lock_irqsave(&priv->lock);
1936	      dq_init(&priv->doneq);
1937	      for (i = 0; i < CAPTURE_READ_NBUF; i++)
1938	        {
1939	          priv->rdbuf[i].curbyte = 0;
1940	          dq_addlast(&priv->rdbuf[i].dq_entry, &priv->pendq);
1941	        }
1942	
1943	      priv->readmode = true;
1944	      spin_unlock_irqrestore(&priv->lock, flags);
1945	      capture_start_dma(priv);
1946	    }
1947	
1948	  for (; ; )
1949	    {
1950	      flags = spin_lock_irqsave(&priv->lock);
1951	      apb = (FAR struct ap_buffer_s *)dq_peek(&priv->doneq);
1952	      readmode = priv->readmode;
1953	      spin_unlock_irqrestore(&priv->lock, flags);
1954	
1955	      if (!readmode)
1956	        {
1957	          return -EAGAIN;
1958	        }
1959	
1960	      if (apb != NULL)
1961	        {
1962	          break;
1963	        }
1964	
1965	      /* Extra posts (stop, a buffer already consumed) only cost one more
1966	       * trip round this loop.
1967	       */
1968	
1969	      ret = nxsem_tickwait(&priv->readsem,
1970	                           MSEC2TICK(CAPTURE_READ_TIMEOUT_MS));
1971	      if (ret == -ETIMEDOUT)
1972	        {
1973	          return -EAGAIN;
1974	        }
1975	
1976	      if (ret < 0)
1977	        {
1978	          return ret;
1979	        }
1980	    }
1981	
1982	  /* The buffer sits in neither pendq nor the DMA while it is in doneq, so
1983	   * it is safe to copy outside the lock.
1984	   */
1985	
1986	  if (apb->curbyte == 0)
1987	    {
1988	      up_invalidate_dcache((uintptr_t)apb->samp,
1989	                           (uintptr_t)apb->samp + apb->nbytes);
1990	    }
1991	
1992	  n = MIN(buflen, (size_t)(apb->nbytes - apb->curbyte));
1993	  memcpy(buffer, apb->samp + apb->curbyte, n);
1994	
1995	  flags = spin_lock_irqsave(&priv->lock);
1996	  if (priv->readmode &&
1997	      dq_peek(&priv->doneq) == (FAR dq_entry_t *)&apb->dq_entry)
1998	    {
1999	      apb->curbyte += n;
2000	      if (apb->curbyte >= apb->nbytes)
2001	        {
2002	          dq_rem(&apb->dq_entry, &priv->doneq);
2003	          apb->curbyte = 0;
2004	          dq_addlast(&apb->dq_entry, &priv->pendq);
2005	          requeue = true;
2006	        }
2007	    }
2008	
2009	  spin_unlock_irqrestore(&priv->lock, flags);
2010	
2011	  if (requeue)
2012	    {
2013	      capture_start_dma(priv);
2014	    }
2015	
2016	  return (int)n;
2017	}
