import serial, time, re, sys

DEV="/dev/ttyUSB0"; BAUD=1000000
KEYS="yzhang/cmd_scripts.sh"

src = open(KEYS, encoding="utf-8").read().splitlines()
def fl(regex):
    for l in src:
        if re.search(regex, l) and not l.lstrip().startswith('#'):
            return l.strip()
    return None

wifi_luv  = fl(r'wapi connect "Luv"')
wifi_vivo = fl(r'wapi connect "vivo')

secrets = []
for c in (wifi_luv, wifi_vivo):
    if c:
        tok = c.split()[-1].strip('"')
        if tok not in secrets: secrets.append(tok)

def redact(data):
    try: s = data.decode('utf-8','replace')
    except Exception: s = str(data)
    for t in secrets: s = s.replace(t, '[REDACTED]')
    return s

s = serial.Serial(DEV, BAUD, timeout=0.3)
s.dtr=False; s.rts=False
s.reset_input_buffer()

def send(cmd, label=None):
    sys.stdout.write("\n>>> %s\n" % (label or cmd)); sys.stdout.flush()
    s.write((cmd + "\r\n").encode('utf-8')); time.sleep(0.4)

def drain(secs, stop_re=None):
    end = time.time()+secs; acc=b""
    while time.time() < end:
        n = s.in_waiting
        if n:
            d = s.read(n); acc += d
            sys.stdout.write(redact(d)); sys.stdout.flush()
            if stop_re and re.search(stop_re, acc.decode('utf-8','replace')):
                return acc
        else:
            time.sleep(0.05)
    return acc

# wake + confirm prompt
send("", "(blank)")
drain(1.5)

# try wifi: Luv first, then vivo
got_ip = False
for label, cmd in (("Luv", wifi_luv), ("vivo X100 Pro", wifi_vivo)):
    if not cmd: continue
    send(cmd, "[secret] wapi connect -> %s" % label)
    out = drain(20, stop_re=r'(got ip|ip4|ip addr|wlan0 ip)')
    txt = out.decode('utf-8','replace')
    if re.search(r'(\d{1,3}\.){3}\d{1,3}', txt):
        got_ip = True
        print("\n=== WIFI OK (%s) ===" % label); sys.stdout.flush()
        break
    print("\n=== no IP from %s, try next ===" % label); sys.stdout.flush()

print("\n=== wifi result: %s ===" % ("OK" if got_ip else "FAILED"))
s.close()
