Now code for creation:

```c
  /* Idle button legend — three lines sharing one left *and* one right edge
   * (两端对齐).  LVGL v9 has no justify align, so every line is a
   * fixed-width, centre-aligned label and the slack between the line's
   * natural width and the block width is turned into per-line letter
   * spacing; the residual (integer px) is halved by the centre align.
   * Hidden for every non-idle state, where the single caption label is
   * used instead. */
  {
    int32_t w[IDLE_HINT_LINES];
    uint32_t glyphs[IDLE_HINT_LINES];
    int32_t block_w = 0;
    int i;

    for (i = 0; i < IDLE_HINT_LINES; i++)
      {
        const char *t = s_idle_hint_lines[i];
        glyphs[i] = utf8_glyph_count(t);
        w[i] = lv_text_get_width(t, (uint32_t)strlen(t),
                                 &lv_font_misans_12_cjk, 0);
        if (w[i] > block_w) block_w = w[i];
      }

    s_pet.hint_box = lv_obj_create(s_pet.screen);
    if (!s_pet.hint_box) goto fail;
    lv_obj_remove_flag(s_pet.hint_box, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(s_pet.hint_box, block_w, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(s_pet.hint_box, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(s_pet.hint_box, 0, 0);
    lv_obj_set_style_pad_all(s_pet.hint_box, 0, 0);
    lv_obj_set_style_pad_row(s_pet.hint_box, 4, 0);
    lv_obj_set_flex_flow(s_pet.hint_box, LV_FLEX_FLOW_COLUMN);
    lv_obj_align(s_pet.hint_box, LV_ALIGN_CENTER, 0, PET_LABEL_DY);

    for (i = 0; i < IDLE_HINT_LINES; i++)
      {
        int32_t gaps = (int32_t)glyphs[i] - 1;
        /* Round to the nearest px so the leftover at each edge is ≤ 0.5 gap. */
        int32_t ls = (gaps > 0 && block_w > w[i])
                     ? (block_w - w[i] + gaps / 2) / gaps : 0;

        s_pet.hint_lbl[i] = lv_label_create(s_pet.hint_box);
        if (!s_pet.hint_lbl[i]) goto fail;
        lv_label_set_text(s_pet.hint_lbl[i], s_idle_hint_lines[i]);
        lv_obj_set_width(s_pet.hint_lbl[i], block_w);
        lv_obj_set_style_text_align(s_pet.hint_lbl[i], LV_TEXT_ALIGN_CENTER, 0);
        lv_obj_set_style_text_letter_space(s_pet.hint_lbl[i], ls, 0);
        lv_obj_set_style_text_color(s_pet.hint_lbl[i],
                                    lv_color_hex(UI_PAL_TEXT_DIM), 0);
        lv_obj_set_style_text_font(s_pet.hint_lbl[i],
                                   &lv_font_misans_12_cjk, 0);
        syslog(LOG_INFO, "[%s] hint[%d] w=%d glyphs=%u letter_space=%d\n",
               TAG, i, (int)w[i], (unsigned)glyphs[i], (int)ls);
      }
  }
```

