/* Idle caption: the on-device button legend, three lines justified to a
 * common left *and* right edge (两端对齐).  S1 (GPIO13) = push-to-talk;
 * S2/S3 long-press = model / new session; the plain tap on S2/S3 scrolls the
 * chat transcript.
 *
 * LVGL v9 has no "justify" text align, so each line is its own fixed-width,
 * centre-aligned label and the slack between the line's natural width and the
 * block width becomes that line's letter spacing (see pet_view_create). */
static const char *const s_idle_hint_lines[] = {
  "S1 按住说话",
  "S2 长按切换模型",
  "S3 长按新建会话",
};

#define IDLE_HINT_LINES \
  ((int)(sizeof(s_idle_hint_lines) / sizeof(s_idle_hint_lines[0])))

/* Glyph count of a UTF-8 string (continuation bytes 10xxxxxx don't count). */
static uint32_t utf8_glyph_count(const char *s)
{
  uint32_t n = 0;

  for (; *s != '\0'; s++)
    {
      if (((uint8_t)*s & 0xc0u) != 0x80u) n++;
    }

  return n;
}

static const char *display_text_for(enum pet_state st)
{
  /* IDLE is drawn by the justified hint block, not by the caption label. */
  return (st == PET_STATE_IDLE) ? "" : s_state_text[st];
}

